-- ============================================================================
-- States and provinces, so two towns with one name stop being one place.
--
-- Linda, 13 Sep 2026: "For the United States, there needs to be a way to add a
-- state. I worked in Annandale, MN, but it puts me in Annandale, VA."
--
-- Two separate faults sat behind that.
--
-- 1. The gazetteer stored ONE row per (country, city name), keeping whichever was
--    most populous. Across the world that silently threw away 1,040 real places:
--    308 ambiguous names in the US alone, 155 in China, 79 in Brazil. Every one
--    of them was a town that could never be picked, and a town that could be
--    picked under someone else's coordinates.
--
-- 2. Nothing recorded WHICH Annandale. The degree engine matches on city name
--    within a country, so Annandale MN and Annandale VA were the same city: two
--    people who have never been within a thousand miles of each other would
--    compute as degree 3.
--
-- So cities now carry admin1 (the GeoNames code, enough to tell two places
-- apart) and, for the US, region (the state code, which is what a person
-- actually says). Schools carry the region of their city.
--
-- THE MATCH RULE IS DELIBERATELY PERMISSIVE: two cities match when their regions
-- agree OR when either region is unknown. 2,120 catalogue schools have no region
-- and never will until someone corrects them, and refusing to match those would
-- silently delete existing, correct connections. Knowing more can separate two
-- places; knowing nothing leaves them as they were.
--
-- Annandale, Minnesota has a population of about 3,300 and is below the GeoNames
-- threshold, so it is not in this data either. public.regions carries a centroid
-- per US state so a town that small can still be added and land in the right
-- state rather than the wrong one.
-- ============================================================================

-- ── cities: which one is it? ────────────────────────────────────────────────
alter table public.cities add column if not exists admin1 text;
alter table public.cities add column if not exists region text;

-- The old key is what discarded 1,040 places.
alter table public.cities drop constraint if exists cities_country_code_name_key;
create unique index if not exists cities_place_key
  on public.cities (country_code, coalesce(admin1, ''), name);
create index if not exists cities_region_idx on public.cities (country_code, region);

-- Every US city (so the picker can show a state) plus every name that repeats
-- inside its own country (so both survive). Existing rows gain their admin1;
-- the ones the old key dropped are inserted.
insert into public.cities (country_code, name, admin1, region, latitude, longitude, population) values
