on conflict (country_code, coalesce(admin1, ''), name) do update
  set admin1 = excluded.admin1,
      region = coalesce(excluded.region, public.cities.region);

-- A row that already existed WITHOUT an admin1 cannot be matched by the new key,
-- so it stays behind as a duplicate of the row just inserted. Remove those: keep
-- the one that knows where it is.
delete from public.cities c
 where c.admin1 is null
   and exists (select 1 from public.cities d
                where d.country_code = c.country_code and d.name = c.name
                  and d.admin1 is not null);

-- ── regions: a place to put a town too small to be listed ───────────────────
create table if not exists public.regions (
  country_code text not null,
  code         text not null,
  name         text not null,
  -- Mean of the state's known cities. Approximate on purpose: it exists so an
  -- unlisted town lands in the right STATE. Degrees are computed from city names,
  -- never from coordinates, so an approximate point moves a map dot and nothing else.
  latitude     double precision not null,
  longitude    double precision not null,
  primary key (country_code, code)
);

