-- Annandale MN is not in the gazetteer and never will be, so a member has to be
-- able to add their own town — the same right they already have for schools.
drop policy if exists cities_insert_member on public.cities;
create policy cities_insert_member on public.cities
  for insert to authenticated with check (public.is_member());
grant insert on public.cities to authenticated;

-- Don't let a second 'Annandale, MN' in behind the first.
create or replace function public.cities_dedupe()
returns trigger language plpgsql security definer set search_path = public as $$
declare existing record;
begin
  new.name := btrim(new.name);
  new.admin1 := nullif(btrim(coalesce(new.admin1, '')), '');
  new.region := nullif(btrim(coalesce(new.region, '')), '');
  if length(new.name) < 2 then
    raise exception 'That city name is too short.' using errcode = '22023';
  end if;
  select * into existing from public.cities c
   where c.country_code = new.country_code
     and lower(c.name) = lower(new.name)
     and coalesce(c.region, '') = coalesce(new.region, '')
   limit 1;
  if found then
    raise exception 'ALREADY_LISTED|%|%', existing.name, coalesce(existing.region, '')
      using errcode = '23505';
  end if;
  return new;
end $$;

drop trigger if exists cities_dedupe_trg on public.cities;
create trigger cities_dedupe_trg before insert on public.cities
  for each row execute function public.cities_dedupe();

alter table public.regions enable row level security;
drop policy if exists regions_read on public.regions;
create policy regions_read on public.regions for select to authenticated using (true);
grant select on public.regions to authenticated;

-- ── schools: which state is this school in? ─────────────────────────────────
alter table public.schools add column if not exists region text;

-- Fill in what we can prove: a school whose city is unambiguous in its country
-- inherits that city's region.
update public.schools s
   set region = c.region
  from public.cities c
 where s.region is null
   and c.country_code = s.country_code
   and c.name = s.city
   and c.region is not null
   and (select count(*) from public.cities d
         where d.country_code = s.country_code and d.name = s.city) = 1;

-- ── The degree engine, now region-aware ─────────────────────────────────────
-- Same six degrees, same precedence. The ONLY change is that "same city" now
-- also requires the regions to agree when both are known.
drop function if exists public.pair_degree(bigint, text, text, date, date, bigint, text, text, date, date);

create or replace function public.pair_degree(
  a_school bigint, a_city text, a_region text, a_country text, a_start date, a_end date,
  b_school bigint, b_city text, b_region text, b_country text, b_start date, b_end date
) returns table (degree smallint, context_type text, context_label text, same_time boolean)
language sql immutable parallel safe as $$
  with t as (
    select public.ranges_overlap(a_start, a_end, b_start, b_end) as same,
           -- unknown region never blocks a match; two known, different ones do
           (a_city is not null and a_city = b_city and a_country = b_country
            and (a_region is null or b_region is null or a_region = b_region)) as same_city
  )
  select
    case
      when a_school = b_school then (case when t.same then 1 else 2 end)
      when t.same_city         then (case when t.same then 3 else 4 end)
      when a_country = b_country then (case when t.same then 5 else 6 end)
    end::smallint,
    case
      when a_school = b_school   then 'school'
      when t.same_city           then 'city'
      when a_country = b_country then 'country'
    end,
    case
      when a_school = b_school then (select name from public.schools where id = a_school)
      -- name the state when we know it, because "Annandale, United States" is
      -- exactly the ambiguity this migration exists to remove
      when t.same_city then a_city
                            || coalesce(', ' || coalesce(a_region, b_region), '')
                            || ', ' || a_country
      when a_country = b_country then a_country
    end,
    t.same
  from t
  where a_country = b_country;   -- no shared country means no relationship at all
$$;

alter function public.pair_degree(bigint, text, text, text, date, date, bigint, text, text, text, date, date)
  set search_path = public;
revoke execute on function public.pair_degree(bigint, text, text, text, date, date, bigint, text, text, text, date, date) from public, anon;
grant execute on function public.pair_degree(bigint, text, text, text, date, date, bigint, text, text, text, date, date) to authenticated;

-- recompute_for_profile has to pass the regions through.
create or replace function public.recompute_for_profile(p uuid)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  n integer;
begin
  delete from public.colleagueships  where profile_a = p or profile_b = p;
  delete from public.shared_contexts where profile_a = p or profile_b = p;

  with mine as (
    select po.school_id, s.city, s.region, s.country, po.start_date, po.end_date
      from public.postings po join public.schools s on s.id = po.school_id
     where po.profile_id = p
  ),
  theirs as (
    select po.profile_id, po.school_id, s.city, s.region, s.country, po.start_date, po.end_date
      from public.postings po join public.schools s on s.id = po.school_id
     where po.profile_id <> p
  ),
  pairs as (
    select t.profile_id as other, d.degree, d.context_type, d.context_label, d.same_time,
           public.overlap_years(m.start_date, m.end_date, t.start_date, t.end_date) as oy
      from mine m
      join theirs t on t.country = m.country
      cross join lateral public.pair_degree(
        m.school_id, m.city, m.region, m.country, m.start_date, m.end_date,
        t.school_id, t.city, t.region, t.country, t.start_date, t.end_date) d
     where d.degree is not null
  ),
  best as (
    select distinct on (other) other, degree, context_type, context_label, same_time, oy
      from pairs
     order by other, degree asc
  ),
  headline as (
    insert into public.colleagueships
      (profile_a, profile_b, degree, context_type, context_label, time_relation, overlap_years, computed_at)
    select least(p, other), greatest(p, other), degree, context_type, context_label,
           case when same_time then 'same time' else 'different time' end,
           case when same_time then oy else '' end,
           now()
      from best
    on conflict (profile_a, profile_b) do update
      set degree = excluded.degree,
          context_type = excluded.context_type,
          context_label = excluded.context_label,
          time_relation = excluded.time_relation,
          overlap_years = excluded.overlap_years,
          computed_at = now()
    returning 1
  )
  insert into public.shared_contexts
    (profile_a, profile_b, degree, context_type, context_label, time_relation, overlap_years)
  select distinct
         least(p, other), greatest(p, other), degree, context_type, context_label,
         case when same_time then 'same time' else 'different time' end,
         case when same_time then oy else '' end
    from pairs
  on conflict do nothing;

  select count(*) into n from public.colleagueships where profile_a = p or profile_b = p;
  return n;
end $$;

-- Schools can change region, which changes who is "same city".
create or replace function public.schools_recompute()
returns trigger language plpgsql security definer set search_path = public as $$
declare r record;
begin
  for r in select distinct profile_id from public.postings where school_id = new.id loop
    perform public.recompute_for_profile(r.profile_id);
  end loop;
  return new;
end $$;

drop trigger if exists schools_recompute_trg on public.schools;
create trigger schools_recompute_trg
  after update of city, region, country on public.schools
  for each row execute function public.schools_recompute();

select public.recompute_all();
